const int LIFE_EXTEND_SCALE = 8;

const int LIFE_EXTEND_MIN = 64;

const int SHAPE_VERTICES_STRIDE = 24;

const int LOCAL_VERTICES_STRIDE = 10;

const int SS_RUNTIME_INVALID_HANDLE = 4294967295;
